('1775660020463', 'Vitamin D3 & K2', 'Myprotein', '1775486652713', '1775492587826,1775492588335,1775492588657,1775492588817', '<p>This upgraded formula brings together two essential vitamins that 
work in tandem — with a higher-strength dose to help you stay on top of 
your health. Each capsule delivers 100μg (4,000 IU) of vitamin D3 and 
100μg of vitamin K2 (MK-7), helping to support normal immune system 
function, bone strength, and calcium balance in the body¹².</p>
<p>Whether you train indoors, spend little time in the sun, or just want
 nutritional backup, this is a convenient way to stay topped up.</p><p><b><u>Key Benefits</u></b><br>100μg (4,000 IU) high-strength vitamin D3 per serving<br>100μg vitamin K2 (MK-7) — the most active, bioavailable form<br>Vitamin D supports immunity, muscle function &amp; bone maintenance<br>Vitamin K supports normal blood clotting &amp; bone health<br>Easy-to-take daily capsule — ideal for low-sunlight months</p>', '["https://res.cloudinary.com/dbxna1ipc/image/upload/v1775659993/bybens-products/Screenshot_2026-04-08_at_16-53-06_Vitamin_D3_K2_Capsules_Vitamins_MYPROTEIN.png"]'::jsonb, '[{"unit":"caps","price":6000,"stock":0,"weight":"90","flavorStock":{"Unflavored":0}}]'::jsonb, '[{"qty":0,"name":"Unflavored"}]'::jsonb, 0, 0, true, '1775387552641', 'active', '<img src="https://res.cloudinary.com/dbxna1ipc/image/upload/v1779398983/bybens-nutritional-facts/product_1775660020463_nutrifacts_0.png" alt="">', '<br>', '2026-04-08 14:53:40.463+00', false),
('1775814664845', 'Creatine MicronPure', 'Prozis', '1775246116909', '1775246117263', '<div>Maximize your strength with <b data-path-to-node="0" data-index-in-node="28">Prozis Creatine MicronPure</b>. This ultra-refined, <b data-path-to-node="0" data-index-in-node="76">micronized creatine monohydrate</b> is engineered for superior solubility and faster absorption compared to standard formulas. Each serving provides pure, high-quality creatine to boost physical performance during high-intensity training. With its neutral flavor and fine texture, it mixes effortlessly into any drink, ensuring a smooth, grit-free experience to help you reach your power and muscle-building goals.</div><div><br></div><div><div class="servings"><p class="serving-size lot-line"> Serving size: <span> 1 scoop(s)(3 g) </span></p><p class="per-container lot-line"> Servings per container:&nbsp;<span> 100</span></p></div><br></div>', '["https://res.cloudinary.com/dbxna1ipc/image/upload/v1775814607/bybens-products/Screenshot_2026-04-10_at_11-46-58_Creatine_MicronPure_300g_-_Build_Muscle_Prozis.png","https://res.cloudinary.com/dbxna1ipc/image/upload/v1775814627/bybens-products/Screenshot_2026-04-10_at_11-47-07_Creatine_MicronPure_300g_-_Build_Muscle_Prozis.png","https://res.cloudinary.com/dbxna1ipc/image/upload/v1775814631/bybens-products/Screenshot_2026-04-10_at_11-47-15_Creatine_MicronPure_300g_-_Build_Muscle_Prozis.png","https://res.cloudinary.com/dbxna1ipc/image/upload/v1775814635/bybens-products/Screenshot_2026-04-10_at_11-47-51_Creatine_MicronPure_300g_-_Build_Muscle_Prozis.png"]'::jsonb, '[{"unit":"g","price":7500,"stock":0,"weight":"300","flavorStock":{"Unflavored":0}}]'::jsonb, '[{"qty":0,"name":"Unflavored"}]'::jsonb, 0, 0, true, '1775387552641', 'active', '<img src="https://res.cloudinary.com/dbxna1ipc/image/upload/v1779399015/bybens-nutritional-facts/product_1775814664845_nutrifacts_0.png" alt="">', '', '2026-04-10 09:51:04.846+00', false),
('1775815333025', 'Ashwagandha Root Extract', 'Prozis', '1775486652713', '1775492587826,1775492588335,1775492588505', '<h4 class="prozis-h4 tblack zeromargin tuppercase zeropadding">A Root with a Rich Heritage</h4>
                    <p class="prozis-p tblack mt10">Grown in the dry regions of India, Nepal, China, and Yemen, Ashwagandha <i>(Withania somnifera)</i> is a <strong>traditional plant long valued in various cultures</strong>. Prozis Ashwagandha Extract is <strong>carefully sourced and encapsulated</strong> to bring this botanical ingredient into your daily routine—<strong>clean, convenient, and easy to take.</strong></p><p class="serving-size lot-line"> Serving size: <span> 1 vegetarian capsule(s) </span></p><p class="per-container lot-line"> Servings per container: <span> 90 </span></p><p class="prozis-p tblack mt10"><br></p>', '["https://res.cloudinary.com/dbxna1ipc/image/upload/v1775815291/bybens-products/Screenshot_2026-04-10_at_11-59-13_Ashwagandha_Extract_450_mg_90_Veg_caps_-_Health_Prozis.png","https://res.cloudinary.com/dbxna1ipc/image/upload/v1775815294/bybens-products/Screenshot_2026-04-10_at_11-59-27_Ashwagandha_Extract_450_mg_90_Veg_caps_-_Health_Prozis.png","https://res.cloudinary.com/dbxna1ipc/image/upload/v1775815297/bybens-products/Screenshot_2026-04-10_at_11-59-37_Ashwagandha_Extract_450_mg_90_Veg_caps_-_Health_Prozis.png"]'::jsonb, '[{"unit":"caps","price":6000,"stock":1,"weight":"90","flavorStock":{"Unflavored":1}}]'::jsonb, '[{"qty":0,"name":"Unflavored"}]'::jsonb, 1, 0, true, '1775387552641', 'active', '<img src="https://res.cloudinary.com/dbxna1ipc/image/upload/v1779399020/bybens-nutritional-facts/product_1775815333025_nutrifacts_0.png" alt="">', '', '2026-04-10 10:02:13.025+00', false),
