('1777811249431', 'Flavour Drops', 'Myprotein', '1775361511130', '1775361511308,1775481224198', '<h3><strong>What are Flavour Drops?</strong></h3>
<p>Cutting fat and sugar from your diet doesn’t have to mean your meals are bland and boring. Our unique <span style="font-size:13px">Flavour Drops</span> let you flavour food and drinks without taking on extra calories.</p>', '["https://res.cloudinary.com/dbxna1ipc/image/upload/v1777811197/bybens-products/drop.avif","https://res.cloudinary.com/dbxna1ipc/image/upload/v1777811200/bybens-products/dropssss.avif","https://res.cloudinary.com/dbxna1ipc/image/upload/v1777811204/bybens-products/dropsdd.avif"]'::jsonb, '[{"unit":"ml","price":2500,"stock":2,"weight":"50","flavorStock":{"Lemon":1,"Chocolate":1}}]'::jsonb, '[{"qty":0,"name":"Chocolate"},{"qty":0,"name":"Lemon"}]'::jsonb, 2, 0, true, '1775387552641', 'active', '<img src="https://res.cloudinary.com/dbxna1ipc/image/upload/v1779398984/bybens-nutritional-facts/product_1777811249431_nutrifacts_0.png" alt="">', '', '2026-05-03 12:27:29.431+00', false),
('1775658975836', '1000mg Magnesium Bisglycinate Tablets​', 'Myprotein', '1775486652713', '1775492587826,1775492588335,1775492588505,1775492588657', '<p>Magnesium is an essential mineral, present in every cell of the body 
and involved in numerous biological processes. Our Magnesium 
Bisglycinate tablets deliver 113mg of elemental magnesium to support 
energy production<sup>2</sup>, fatigue reduction,¹ muscle function,² and electrolyte balance⁴</p>
<p>Whether you''re pushing through workouts or maintaining an active lifestyle, this essential mineral is here to support you.</p><p><b><u>Key Benefits</u></b><br>113mg elemental magnesium per serving<br>Supports muscle function and energy production<br>Helps reduce tiredness and fatigue<br>Plays a role in electrolyte balance</p>', '["https://res.cloudinary.com/dbxna1ipc/image/upload/v1775658912/bybens-products/Screenshot_2026-04-08_at_16-34-44_1000mg_Magnesium_Bisglycinate_Tablets_Myprotein_UK.png","https://res.cloudinary.com/dbxna1ipc/image/upload/v1777807424/bybens-products/bis.avif","https://res.cloudinary.com/dbxna1ipc/image/upload/v1777807454/bybens-products/bisdd.avif"]'::jsonb, '[{"unit":"caps","price":6000,"stock":0,"weight":"90","flavorStock":{"Unflavored":0}}]'::jsonb, '[{"qty":0,"name":"Unflavored"}]'::jsonb, 0, 0, true, '1775387552641', 'active', '<img src="https://res.cloudinary.com/dbxna1ipc/image/upload/v1779398984/bybens-nutritional-facts/product_1775658975836_nutrifacts_0.png" alt="">', '<br>', '2026-04-08 14:36:15.836+00', false),
('1775815978927', 'B Complex', 'Prozis', '1775486652713', '1775492587826,1775492588335,1775492588657', '<div>B-Complex by Prozis provides at least 100% of each B-vitamin’s NRV 
(Nutrient Reference Value). Although we recommend obtaining your 
